INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6477134, 962590, 76335, '<td valign="top">A cow should <i>never</i> be centered in the frame. Points to you for doing so. (Yes, nice long exposure too.)</td>', 'A cow should never be centered in the frame. Points to you for doing so. (Yes, nice long exposure too.)', '2011-07-20 18:07:28.000000', NULL, 1),
(6477136, 962611, 76335, '<td valign="top">No rules street photography?</td>', 'No rules street photography?', '2011-07-20 18:08:24.000000', NULL, 1),
(6477137, 962767, 76335, '<td valign="top">You''ve turned him into a dinosaur!</td>', 'You''ve turned him into a dinosaur!', '2011-07-20 18:08:47.000000', NULL, 1),
(6477140, 962665, 76335, '<td valign="top">The oranges and yellows (distant cloud) feel unreal, too saturated. Beautiful scene though.</td>', 'The oranges and yellows (distant cloud) feel unreal, too saturated. Beautiful scene though.', '2011-07-20 18:09:34.000000', NULL, 1),
(6477141, 962765, 63244, '<td valign="top">Beautiful detail and nice pose for the model.</td>', 'Beautiful detail and nice pose for the model.', '2011-07-20 18:09:52.000000', NULL, 1),
(6477144, 962801, 63244, '<td valign="top">This is really cool. Need to watch judi''s tutorial and give this a try! Beautiful!!</td>', 'This is really cool. Need to watch judi''s tutorial and give this a try! Beautiful!!', '2011-07-20 18:11:42.000000', NULL, 1),
(6477146, 962808, 76335, '<td valign="top">I have a feeling I know what this is all about. Interesting we both chased down our kids with our disassembled cameras. I thought it interesting that you chose to do yours in black and white; the crazy colors seem to be a big part of whack appeal. Anyway, the choice to desaturate gives it a beautifully classic feel -- a dimension I hadn''t explored. <br/> <br/>Stunning as usual.</td>', 'I have a feeling I know what this is all about. Interesting we both chased down our kids with our disassembled cameras. I thought it interesting that you chose to do yours in black and white; the crazy colors seem to be a big part of whack appeal. Anyway, the choice to desaturate gives it a beautifully classic feel -- a dimension I hadn''t explored.  Stunning as usual.', '2011-07-20 18:15:39.000000', NULL, 1),
(6477291, 962801, 135629, '<td valign="top">Very cool! I may have to check that tutorial out myself :)</td>', 'Very cool! I may have to check that tutorial out myself :)', '2011-07-20 21:18:04.000000', NULL, 1),
(6477372, 962832, 50695, '<td valign="top">gorgeous</td>', 'gorgeous', '2011-07-21 00:09:14.000000', NULL, 1),
(6477451, 962719, 54645, '<td valign="top">Stark, yet excitingly bland...must be the light and shadows. Despite the blood oozing from the wounds of this razor sharp image (can I borrow that patch?), I like it. And stop looking at me like that, it''s creepy! 8</td>', 'Stark, yet excitingly bland...must be the light and shadows. Despite the blood oozing from the wounds of this razor sharp image (can I borrow that patch?), I like it. And stop looking at me like that, it''s creepy! 8', '2011-07-21 02:28:07.000000', NULL, 1),
(6477454, 962627, 54645, '<td valign="top">Reminds me of <img alt="'' . substr(''//www.dpchallenge.com/images/user_icon/21.gif'', strrpos(''//www.dpchallenge.com/images/user_icon/21.gif'', ''/'') + 1) . ''" border="0" src="//www.dpchallenge.com/images/user_icon/21.gif"/> <a href="//www.dpchallenge.com/profile.php?USER_ID=100393" rel="nofollow" target="_blank">paulbtlw</a> with the exception of the sharpening. Beautiful model and light.</td>', 'Reminds me of  paulbtlw with the exception of the sharpening. Beautiful model and light.', '2011-07-21 02:33:13.000000', NULL, 1),
(6477455, 962817, 54645, '<td valign="top">Where did you get the gremlins?</td>', 'Where did you get the gremlins?', '2011-07-21 02:33:48.000000', NULL, 1),
(6477456, 962590, 54645, '<td valign="top">Great shock value.  Unique, well done.</td>', 'Great shock value.  Unique, well done.', '2011-07-21 02:35:00.000000', NULL, 1),
(6477457, 962767, 54645, '<td valign="top">Lovely DOF and tones. You know, he looks like he could use a good polish! 8</td>', 'Lovely DOF and tones. You know, he looks like he could use a good polish! 8', '2011-07-21 02:36:02.000000', NULL, 1),
(6477458, 962676, 54645, '<td valign="top">The foreground vehicle is fantastic. Bit bummed that you lost your DOF via the tone mapping, an odd visual illusion. When you fix that flat, I have a gathering to cater.</td>', 'The foreground vehicle is fantastic. Bit bummed that you lost your DOF via the tone mapping, an odd visual illusion. When you fix that flat, I have a gathering to cater.', '2011-07-21 02:39:03.000000', NULL, 1),
(6477459, 962615, 54645, '<td valign="top">Wonderful portrait, strikes me as a <img alt="'' . substr(''//www.dpchallenge.com/images/user_icon/21.gif'', strrpos(''//www.dpchallenge.com/images/user_icon/21.gif'', ''/'') + 1) . ''" border="0" src="//www.dpchallenge.com/images/user_icon/21.gif"/> <a href="//www.dpchallenge.com/profile.php?USER_ID=113156" rel="nofollow" target="_blank">jagar</a>...signature contrast and compositional thought. The reflection is quite interesting in that the crutches are not present, as if we are seeing the man without the disability. It is this nuance that makes this a dynamic photograph, one to remember.</td>', 'Wonderful portrait, strikes me as a  jagar...signature contrast and compositional thought. The reflection is quite interesting in that the crutches are not present, as if we are seeing the man without the disability. It is this nuance that makes this a dynamic photograph, one to remember.', '2011-07-21 02:44:48.000000', NULL, 1),
(6477460, 962642, 54645, '<td valign="top">Fantastic feel, the arrogance of the flower to survive and remain perky is mind blowing. 10</td>', 'Fantastic feel, the arrogance of the flower to survive and remain perky is mind blowing. 10', '2011-07-21 02:45:35.000000', NULL, 1),
(6477461, 962577, 54645, '<td valign="top">You leveraged the shadows quite nicely, every little piece of the frame has something interesting to explore, allowing my own story to grow. Well done. 9</td>', 'You leveraged the shadows quite nicely, every little piece of the frame has something interesting to explore, allowing my own story to grow. Well done. 9', '2011-07-21 02:47:22.000000', NULL, 1),
(6477515, 962567, 28427, '<td valign="top">Very minimalistic.  Maybe the boat is a tad too soft for me.</td>', 'Very minimalistic.  Maybe the boat is a tad too soft for me.', '2011-07-21 06:56:03.000000', NULL, 1),
(6477722, 962567, 76335, '<td valign="top">It''s actually very contrasty if you look at it at the right angle. Perfect.</td>', 'It''s actually very contrasty if you look at it at the right angle. Perfect.', '2011-07-21 14:00:36.000000', NULL, 1),
