INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6481264, 962578, 96751, '<td valign="top">Judi!!!!!!!!  Fantabulous! Congrats on a well-deserved ribbon. I''m seriously amazed you got ANY shots with the horse, using strobes!  I did a pet portrait with a horse, and I couldn''t even use a reflector.  Made the horse VERY nervous.  Amazing you pulled this off, to such spectacular results.</td>', 'Judi!!!!!!!!  Fantabulous! Congrats on a well-deserved ribbon. I''m seriously amazed you got ANY shots with the horse, using strobes!  I did a pet portrait with a horse, and I couldn''t even use a reflector.  Made the horse VERY nervous.  Amazing you pulled this off, to such spectacular results.', '2011-07-26 02:11:10.000000', NULL, 0),
